import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_runtime.h>

extern "C" __global__ void conv3d_k331_s1_p0_d1_g1_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    float* __restrict__ y,
    const int N,
    const int Cin,
    const int A,
    const int B,
    const int L,
    const int Cout,
    const int Aout,
    const int Bout,
    const bool has_bias
) {
    const long long total = (long long)N * Cout * Aout * Bout * L;
    const long long idx = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total) return;

    int l = (int)(idx % L);
    long long t = idx / L;

    int bo = (int)(t % Bout);
    t /= Bout;

    int ao = (int)(t % Aout);
    t /= Aout;

    int co = (int)(t % Cout);
    int n = (int)(t / Cout);

    float acc = has_bias ? b[co] : 0.0f;

    for (int c = 0; c < Cin; ++c) {
        const float* x_base = x + ((((long long)n * Cin + c) * A + ao) * B + bo) * L;
        const float* w_base = w + (((long long)co * Cin + c) * 9);

        #pragma unroll
        for (int ka = 0; ka < 3; ++ka) {
            #pragma unroll
            for (int kb = 0; kb < 3; ++kb) {
                const float xv = x_base[((long long)ka * B + kb) * L + l];
                const float wv = w_base[ka * 3 + kb];
                acc = fmaf(xv, wv, acc);
            }
        }
    }

    y[idx] = acc;
}

torch::Tensor conv3d_asym_forward(torch::Tensor x, torch::Tensor weight, c10::optional<torch::Tensor> bias) {
    TORCH_CHECK(x.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "input must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    TORCH_CHECK(x.dim() == 5, "input must be NCDHW/NCHWD-style 5D");
    TORCH_CHECK(weight.dim() == 5, "weight must be 5D");
    TORCH_CHECK(weight.size(2) == 3 && weight.size(3) == 3 && weight.size(4) == 1,
                "only kernel (3,3,1) is supported");
    TORCH_CHECK(x.size(1) == weight.size(1), "input channels mismatch");

    x = x.contiguous();
    weight = weight.contiguous();

    const c10::cuda::CUDAGuard device_guard(x.device());

    const int N = (int)x.size(0);
    const int Cin = (int)x.size(1);
    const int A = (int)x.size(2);
    const int B = (int)x.size(3);
    const int L = (int)x.size(4);
    const int Cout = (int)weight.size(0);

    const int Aout = A - 2;
    const int Bout = B - 2;
    const int Lout = L;
    TORCH_CHECK(Aout > 0 && Bout > 0 && Lout > 0, "invalid output shape");

    auto y = torch::empty({N, Cout, Aout, Bout, Lout}, x.options());

    const long long total = (long long)N * Cout * Aout * Bout * Lout;
    if (total == 0) return y;

    const bool has_bias = bias.has_value();
    TORCH_CHECK(!has_bias || bias.value().is_cuda(), "bias must be CUDA");
    TORCH_CHECK(!has_bias || bias.value().scalar_type() == at::kFloat, "bias must be float32");
    TORCH_CHECK(!has_bias || bias.value().numel() == Cout, "bias shape mismatch");
    torch::Tensor bias_contiguous;
    const float* b_ptr = nullptr;
    if (has_bias) {
        bias_contiguous = bias.value().contiguous();
        b_ptr = bias_contiguous.data_ptr<float>();
    }

    const int threads = 256;
    const long long blocks_ll = (total + threads - 1) / threads;
    TORCH_CHECK(blocks_ll <= 0x7fffffffLL, "grid too large");
    const dim3 blocks((unsigned int)blocks_ll);

    auto stream = at::cuda::getCurrentCUDAStream();
    conv3d_k331_s1_p0_d1_g1_kernel<<<blocks, threads, 0, stream.stream()>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        b_ptr,
        y.data_ptr<float>(),
        N, Cin, A, B, L, Cout, Aout, Bout, has_bias
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();

    return y;
}
"""

_cpp_src = "torch::Tensor conv3d_asym_forward(torch::Tensor x, torch::Tensor weight, c10::optional<torch::Tensor> bias);"

_conv3d_asym = load_inline(
    name="conv3d_asym_k331_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["conv3d_asym_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
    verbose=False,
)


